import {settlementTotals} from './commission-exchange.js';
import {parseAmount} from './amount-input.js';
export function sanitizeFinance(input={},previous={}){const out={};out.currency=['USD','BOB'].includes(input.currency)?input.currency:previous.currency||'';out.payoutCurrency=['USD','BOB'].includes(input.payoutCurrency)?input.payoutCurrency:out.currency;for(const key of ['exchangeRate','receivedRate']){const n=parseAmount(input[key]);if(n!==null&&(!Number.isFinite(n)||n<=0||n>1000))throw Error('El tipo de cambio debe ser mayor que cero y menor que 1,000 Bs por dólar.');out[key]=n;}out.mode=['percent','fixed','margin'].includes(input.mode)?input.mode:'percent';for(const key of ['minSalePrice','ownerTarget','rate','fixedCommission','salePrice','costs','received']){const value=parseAmount(input[key]);if(value!==null&&(!Number.isFinite(value)||value<0||value>1000000000))throw Error('Revisa el importe privado: '+key);out[key]=value;}if(out.rate!==null&&out.rate>100)throw Error('La comisión porcentual debe estar entre 0 y 100.');for(const key of ['saleDate','ownerName','notes','belowMinimumApproval'])out[key]=String(input[key]||'').trim().slice(0,key==='notes'?2000:300);if(out.saleDate&&!/^\d{4}-\d{2}-\d{2}$/.test(out.saleDate))throw Error('Revisa la fecha de venta.');if(['minSalePrice','ownerTarget','fixedCommission','salePrice','costs','received'].some(k=>out[k]>0)&&!out.currency)throw Error('Selecciona la moneda del acuerdo privado.');if(out.salePrice!==null){if(out.salePrice<=0)throw Error('El precio final de venta debe ser mayor que cero.');if(out.mode==='percent'&&out.rate===null)throw Error('Indica el porcentaje pactado de comisión.');if(out.mode==='fixed'&&out.fixedCommission===null)throw Error('Indica la comisión fija pactada.');if(out.mode==='margin'&&out.ownerTarget===null)throw Error('Indica cuánto debe recibir el propietario.');if(out.minSalePrice!==null&&out.salePrice<out.minSalePrice&&!out.belowMinimumApproval)throw Error('El precio final está bajo el mínimo autorizado. Registra la autorización adicional del propietario.');const result=financeTotals(out);if(result.gross>out.salePrice)throw Error('La comisión no puede superar el precio de venta.');if(out.payoutCurrency!==out.currency&&(!out.exchangeRate||((out.received||0)>0&&!out.receivedRate)))throw Error('Indica el tipo de cambio acordado y, si hubo cobro, el aplicado al cobrar (Bs por US$ 1).');if(settlementTotals(out,result).receivedBase>Math.max(0,result.gross)+0.01)throw Error('Lo cobrado de comisión supera la comisión generada.');}return out;}
const round=n=>Math.round((n+Number.EPSILON)*100)/100;
export function financeTotals(f={}){if(!(Number(f.salePrice)>0))return{recorded:false,gross:0,net:0,ownerPayout:0,received:0,pending:0};const sale=Number(f.salePrice),gross=round(f.mode==='margin'?sale-Number(f.ownerTarget||0):f.mode==='fixed'?Number(f.fixedCommission||0):sale*Number(f.rate||0)/100),costs=Number(f.costs||0),received=Number(f.received||0);return{recorded:true,sale,gross,net:round(gross-costs),ownerPayout:round(sale-gross),costs,received,pending:round(Math.max(0,gross-received)),belowMinimum:f.minSalePrice!==null&&f.minSalePrice!==undefined&&sale<Number(f.minSalePrice)};}
export function financeSummary(vehicles){return['BOB','USD'].map(currency=>{const records=vehicles.filter(v=>v.status==='sold'&&v.privateFinance?.currency===currency&&financeTotals(v.privateFinance).recorded);const totals=records.reduce((a,v)=>{const t=financeTotals(v.privateFinance),settled=settlementTotals(v.privateFinance,t);t.received=settled.receivedBase;t.pending=settled.pendingBase;for(const key of ['sale','gross','net','costs','received','pending'])a[key]=round(a[key]+t[key]);return a;},{sale:0,gross:0,net:0,costs:0,received:0,pending:0});return{currency,count:records.length,...totals};});}
